(()=>{'use strict';function start(){const config=document.querySelector('#packshots133');if(!config)return;const data=JSON.parse(config.textContent),shadow=document.querySelector('#ark-local-purchase')?.shadowRoot,scope=shadow||document;
function update(){let key;if(shadow)key=scope.querySelector('[name=pack]:checked')?.value;else if(data.kind==='catalog')key=scope.querySelector('[data-pack][aria-checked=true]')?.dataset.pack;else key=JSON.stringify(data.options.map((_,i)=>scope.querySelector('[data-option63="'+i+'"][aria-pressed=true]')?.dataset.value63));
const match=data.entries[key],art=scope.querySelector(shadow?'.product-visual':data.kind==='catalog'?'.pack-photo':'.selected-art63');if(!art)return;const stage=art.querySelector('#bottle-stage,.pack-render,[data-legacy-pack-art133]')||art;
if(!match){stage.removeAttribute('data-owner-packshot133');art.removeAttribute('data-owner-art133');const fallback=data.fallbacks?.[key];if(fallback){if(stage===art){const image=art.querySelector('img');if(image)image.src=fallback.image;}else{stage.dataset.count=String(fallback.count);stage.replaceChildren(...Array.from({length:fallback.count},()=>{const image=document.createElement('img');image.src=fallback.image;image.alt='';return image;}));}}return;}
stage.setAttribute('data-owner-packshot133','');art.setAttribute('data-owner-art133','');let image=stage.querySelector('img');if(!image){image=document.createElement('img');stage.prepend(image);}for(const other of [...stage.querySelectorAll('img')].slice(1))other.remove();if(image.getAttribute('src')!==match.image)image.src=match.image;image.width=image.height=480;image.decoding='async';image.alt='';stage.dataset.count='1';}
if(shadow){const style=document.createElement('style');style.textContent="/* One supplied complete package photograph, never cloned into another collage. */\n:host [data-owner-art133] [data-owner-packshot133]{position:absolute!important;inset:0!important;display:block!important;width:100%!important;height:100%!important;padding:0!important;margin:0!important;overflow:hidden;transform:none!important}\n:host [data-owner-art133]{position:relative;overflow:hidden}\n:host [data-owner-packshot133]>img{position:absolute!important;inset:0!important;display:block!important;width:100%!important;height:100%!important;max-width:100%!important;max-height:100%!important;object-fit:contain!important;padding:0!important;margin:0!important;transform:none!important;mix-blend-mode:normal!important}\n:host .selected-art63[data-owner-art133]>img{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;object-fit:contain!important;margin:0!important;transform:none!important}\n:host .selected-art63[data-owner-art133]>.saving63,:host [data-owner-art133]>.total-discount{z-index:2}\n";shadow.append(style);}
const target=shadow||document.querySelector('.product-content');target?.addEventListener('click',update);target?.addEventListener('change',update);update();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();
